query:
query dashboardMVP {
  viewer {
    id
    ... on Member {
      players(mvp: true) {
        id
        session {
          id
          name
          __typename
        }
        division {
          id
          __typename
        }
        league {
          id
          slug
          __typename
        }
        team {
          id
          name
          __typename
        }
        ... on EightBallPlayer {
          pa
          ppm
          rank
          session {
            name
            __typename
          }
          matchesPlayed
          matchesNeededToQualify
          __typename
        }
        ... on NineBallPlayer {
          pa
          ppm
          rank
          session {
            name
            __typename
          }
          matchesPlayed
          matchesNeededToQualify
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
